# 时间序列基础检验：自动识别时间列，仅输出 JSON report
import io
import re
import numpy as np
import pandas as pd

value_column = {{value_column}}


def _to_frame(value):
    if isinstance(value, pd.DataFrame):
        return value.copy()
    if isinstance(value, bytes):
        for encoding in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
            try:
                return pd.read_csv(io.StringIO(value.decode(encoding)))
            except UnicodeDecodeError:
                continue
        raise RuntimeError('CSV 编码无法识别')
    if isinstance(value, str):
        return pd.read_csv(io.StringIO(value.lstrip('\ufeff')))
    raise RuntimeError('输入 data 必须是 CSV 文本或 DataFrame')


def _is_blank(value):
    return bool(pd.isna(value) or str(value).strip() == '')


def _normalise_date_text(value):
    if _is_blank(value):
        return None
    text = str(value).strip()
    text = text.replace('年', '-').replace('月', '-').replace('日', '')
    month_only = re.fullmatch(r'(\d{4})[.\-/](\d{1,2})[.\-/]?', text)
    if month_only:
        return f'{month_only.group(1)}-{int(month_only.group(2)):02d}-01'
    full_date = re.fullmatch(r'(\d{4})[.\-/](\d{1,2})[.\-/](\d{1,2})(.*)', text)
    if full_date:
        return f'{full_date.group(1)}-{int(full_date.group(2)):02d}-{int(full_date.group(3)):02d}{full_date.group(4)}'
    return text


def _parse_dates(series):
    normalised = series.map(_normalise_date_text)
    try:
        return pd.to_datetime(normalised, errors='coerce', format='mixed')
    except (TypeError, ValueError):
        return pd.to_datetime(normalised, errors='coerce')


def _detect_time_column(frame, excluded):
    keywords = ('时间', '日期', '年月', '月份', 'date', 'time', 'timestamp')
    candidates = []
    for index, column in enumerate(frame.columns):
        if column in excluded:
            continue
        name = str(column).lower()
        named = any(keyword in name for keyword in keywords)
        if pd.api.types.is_numeric_dtype(frame[column]) and not named:
            continue
        parsed = _parse_dates(frame[column])
        valid_count = int(parsed.notna().sum())
        if valid_count == 0:
            continue
        ratio = valid_count / max(1, len(frame))
        score = ratio + (2.0 if named else 0.0) - index * 1e-6
        candidates.append((score, ratio, column, parsed))
    if not candidates:
        raise RuntimeError('没有自动识别到时间列；请把时间列命名为“日期”“时间”“date”或“timestamp”，并使用可识别的时间格式')
    candidates.sort(key=lambda item: item[0], reverse=True)
    _, ratio, column, parsed = candidates[0]
    if ratio < 0.6:
        raise RuntimeError('自动识别到的时间列有效时间不足 60%，请检查时间格式或缺失值')
    return column, parsed


def _format_timestamp(value):
    stamp = pd.Timestamp(value)
    if stamp.hour == 0 and stamp.minute == 0 and stamp.second == 0 and stamp.microsecond == 0 and stamp.nanosecond == 0:
        return stamp.strftime('%Y-%m-%d')
    if stamp.microsecond == 0 and stamp.nanosecond == 0:
        return stamp.strftime('%Y-%m-%d %H:%M:%S')
    return stamp.isoformat()


def _format_interval(nanoseconds):
    seconds = nanoseconds / 1_000_000_000
    units = [
        (86400, '天'),
        (3600, '小时'),
        (60, '分钟'),
        (1, '秒'),
    ]
    for size, label in units:
        value = seconds / size
        if abs(value - round(value)) < 1e-9:
            return f'{int(round(value))} {label}'
    return f'{seconds:g} 秒'


if data is None:
    raise RuntimeError('请先连接并运行上游的 CSV 数据导入插件')
frame = _to_frame(data)
if frame.empty:
    raise RuntimeError('CSV 是空表，无法进行时间序列基础检验')
if not value_column or value_column not in frame.columns:
    raise RuntimeError('请选择有效的检测列（单选）')

time_column, parsed_times = _detect_time_column(frame, {value_column})
sample_size = int(len(frame))

raw_values = frame[value_column]
value_missing_mask = raw_values.map(_is_blank)
numeric_values = pd.to_numeric(raw_values, errors='coerce')
value_invalid_mask = (~value_missing_mask) & numeric_values.isna()
value_missing_count = int(value_missing_mask.sum())
value_invalid_count = int(value_invalid_mask.sum())

time_missing_mask = frame[time_column].map(_is_blank)
time_invalid_mask = (~time_missing_mask) & parsed_times.isna()
time_missing_count = int(time_missing_mask.sum())
time_invalid_count = int(time_invalid_mask.sum())

valid_in_original_order = parsed_times.dropna().reset_index(drop=True)
disorder_indexes = []
for index in range(1, len(valid_in_original_order)):
    if valid_in_original_order.iloc[index] < valid_in_original_order.iloc[index - 1]:
        disorder_indexes.append(index + 1)
is_ordered = len(disorder_indexes) == 0

valid_times = parsed_times.dropna()
duplicate_mask = valid_times.duplicated(keep=False)
duplicate_values = valid_times[duplicate_mask]
duplicate_counts = duplicate_values.value_counts().sort_index()
duplicate_times = [_format_timestamp(value) for value in duplicate_counts.index[:100]]
duplicate_time_point_count = int(len(duplicate_counts))
duplicate_row_count = int(sum(int(count) - 1 for count in duplicate_counts.tolist()))

unique_times = pd.DatetimeIndex(valid_times.drop_duplicates().sort_values())
if len(unique_times) >= 2:
    interval_nanoseconds = np.asarray([
        int((unique_times[index] - unique_times[index - 1]).value)
        for index in range(1, len(unique_times))
    ], dtype=np.int64)
    counts = pd.Series(interval_nanoseconds).value_counts()
    highest_count = int(counts.max())
    expected_nanoseconds = int(min(int(value) for value, count in counts.items() if int(count) == highest_count))
    is_equal_interval = bool(np.all(interval_nanoseconds == expected_nanoseconds))
    expected_interval = _format_interval(expected_nanoseconds)
    expected_interval_seconds = expected_nanoseconds / 1_000_000_000
else:
    interval_nanoseconds = np.asarray([], dtype=np.int64)
    expected_nanoseconds = None
    is_equal_interval = False
    expected_interval = None
    expected_interval_seconds = None

missing_time_point_count = 0
missing_time_points = []
missing_time_points_truncated = False
if expected_nanoseconds is not None and expected_nanoseconds > 0:
    for left, right in zip(unique_times[:-1], unique_times[1:]):
        gap_nanoseconds = int(right.value - left.value)
        if gap_nanoseconds <= expected_nanoseconds or gap_nanoseconds % expected_nanoseconds != 0:
            continue
        gap_count = gap_nanoseconds // expected_nanoseconds - 1
        missing_time_point_count += int(gap_count)
        available = max(0, 100 - len(missing_time_points))
        for step in range(1, min(int(gap_count), available) + 1):
            missing_time_points.append(_format_timestamp(left + pd.Timedelta(expected_nanoseconds * step, unit='ns')))
        if gap_count > available:
            missing_time_points_truncated = True

missing_check_passed = (
    value_missing_count == 0
    and value_invalid_count == 0
    and time_missing_count == 0
    and time_invalid_count == 0
    and missing_time_point_count == 0
)
duplicate_check_passed = duplicate_time_point_count == 0
sample_check_passed = sample_size > 0

report = {
    'time_column': str(time_column),
    'value_column': str(value_column),
    'sample_size': sample_size,
    'all_passed': bool(
        is_ordered
        and is_equal_interval
        and missing_check_passed
        and duplicate_check_passed
        and sample_check_passed
    ),
    'checks': {
        'time_order': {
            'passed': bool(is_ordered),
            'is_ordered': bool(is_ordered),
            'disorder_count': int(len(disorder_indexes)),
            'disorder_positions': [int(index) for index in disorder_indexes[:100]],
            'details_truncated': bool(len(disorder_indexes) > 100),
        },
        'equal_interval': {
            'passed': bool(is_equal_interval),
            'is_equal': bool(is_equal_interval),
            'expected_interval': expected_interval,
            'expected_interval_seconds': expected_interval_seconds,
            'unique_time_point_count': int(len(unique_times)),
            'inference_method': '最常见间隔；并列时取较小间隔',
        },
        'missing_values': {
            'passed': bool(missing_check_passed),
            'value_missing_count': value_missing_count,
            'value_invalid_count': value_invalid_count,
            'value_problem_count': int(value_missing_count + value_invalid_count),
            'time_missing_count': time_missing_count,
            'time_invalid_count': time_invalid_count,
            'missing_time_point_count': int(missing_time_point_count),
            'missing_time_points': missing_time_points,
            'missing_time_points_truncated': bool(missing_time_points_truncated),
        },
        'duplicate_time_points': {
            'passed': bool(duplicate_check_passed),
            'duplicate_time_point_count': duplicate_time_point_count,
            'duplicate_row_count': duplicate_row_count,
            'duplicate_times': duplicate_times,
            'details_truncated': bool(duplicate_time_point_count > 100),
        },
        'sample_size': {
            'count': sample_size,
            'passed': bool(sample_check_passed),
        },
    },
}
return {'report': report}
